#!/usr/bin/env node
/**
 * FELDesign token generator.
 *
 * Reads the canonical token file (infra/design_tokens.json) and emits:
 *   - src/design/tokens.css  -> CSS custom properties on :root (+ reduced-motion overrides)
 *   - src/design/tokens.js   -> JS mirror (raw values + cssVar helpers)
 *
 * Usage: npm run tokens   (from frontend/)
 *
 * infra/design_tokens.json is CANONICAL. Never hand-edit the generated files.
 */
const fs = require("fs");
const path = require("path");

const SRC = path.resolve(__dirname, "../../infra/design_tokens.json");
const OUT_DIR = path.resolve(__dirname, "../src/design");
const tokens = JSON.parse(fs.readFileSync(SRC, "utf8"));
const PREFIX = tokens.prefix || "fel";

const isMeta = (key) => key.startsWith("$") || key.startsWith("_");

/** Flatten {group: {name: value | {sub: value}}} into [cssVarName, value] pairs. */
function flatten(group, obj, out = []) {
  for (const [key, value] of Object.entries(obj)) {
    if (isMeta(key)) continue;
    if (value !== null && typeof value === "object") {
      for (const [sub, subValue] of Object.entries(value)) {
        if (isMeta(sub)) continue;
        out.push([`--${PREFIX}-${group}-${key}-${sub}`, String(subValue)]);
      }
    } else {
      out.push([`--${PREFIX}-${group}-${key}`, String(value)]);
    }
  }
  return out;
}

const GROUPS = ["color", "font", "text", "space", "radius", "elevation", "motion"];

// ---------- tokens.css ----------
let css = `/* AUTO-GENERATED by scripts/generate-design-tokens.js from infra/design_tokens.json (v${tokens.version}).\n * Do not edit by hand — edit the JSON and run \`npm run tokens\`.\n */\n:root {\n`;
for (const group of GROUPS) {
  css += `  /* ${group} */\n`;
  for (const [name, value] of flatten(group, tokens[group])) {
    css += `  ${name}: ${value};\n`;
  }
}
css += `}\n\n/* Reduce-motion: collapse all motion durations to near-zero so transitions\n * and keyframe animations complete instantly but transitionend still fires. */\n@media (prefers-reduced-motion: reduce) {\n  :root {\n    --${PREFIX}-motion-fast: 1ms;\n    --${PREFIX}-motion-normal: 1ms;\n    --${PREFIX}-motion-slow: 1ms;\n    --${PREFIX}-motion-stagger: 0ms;\n  }\n}\n`;

// ---------- tokens.js ----------
const jsSafe = (obj) =>
  Object.fromEntries(Object.entries(obj).filter(([k]) => !isMeta(k)));

const js = `/* AUTO-GENERATED by scripts/generate-design-tokens.js from infra/design_tokens.json (v${tokens.version}).
 * Do not edit by hand — edit the JSON and run \`npm run tokens\`.
 *
 * Raw values for JS consumers (canvas, WebGL, web audio, rAF animations).
 * For styling, prefer the CSS variables in tokens.css: var(--${PREFIX}-color-accent-primary) etc.
 */
export const color = ${JSON.stringify(jsSafe(tokens.color), null, 2)};

export const font = ${JSON.stringify(jsSafe(tokens.font), null, 2)};

export const text = ${JSON.stringify(jsSafe(tokens.text), null, 2)};

export const space = ${JSON.stringify(jsSafe(tokens.space), null, 2)};

export const radius = ${JSON.stringify(jsSafe(tokens.radius), null, 2)};

export const elevation = ${JSON.stringify(jsSafe(tokens.elevation), null, 2)};

/** Durations/easings as strings ("120ms"). Use motionMs for numeric values. */
export const motion = ${JSON.stringify(jsSafe(tokens.motion), null, 2)};

/** Motion durations in numbers (ms) for JS-driven animation. */
export const motionMs = {
  fast: ${parseInt(tokens.motion.fast, 10)},
  normal: ${parseInt(tokens.motion.normal, 10)},
  slow: ${parseInt(tokens.motion.slow, 10)},
  stagger: ${parseInt(tokens.motion.stagger, 10)},
};

/** Audio mix levels in dBFS relative to master (not CSS-facing). */
export const audio = ${JSON.stringify(jsSafe(tokens.audio), null, 2)};

/** cssVar("color", "accent-primary") -> "var(--${PREFIX}-color-accent-primary)" */
export const cssVar = (group, name, sub) =>
  \`var(--${PREFIX}-\${group}-\${name}\${sub ? \`-\${sub}\` : ""})\`;

/** True when the user prefers reduced motion (guard rAF/JS-driven animation with this). */
export const prefersReducedMotion = () =>
  typeof window !== "undefined" &&
  window.matchMedia &&
  window.matchMedia("(prefers-reduced-motion: reduce)").matches;

const felTokens = { color, font, text, space, radius, elevation, motion, motionMs, audio, cssVar, prefersReducedMotion };
export default felTokens;
`;

fs.mkdirSync(OUT_DIR, { recursive: true });
fs.writeFileSync(path.join(OUT_DIR, "tokens.css"), css);
fs.writeFileSync(path.join(OUT_DIR, "tokens.js"), js);
console.log(`FELDesign tokens v${tokens.version} -> ${path.relative(process.cwd(), OUT_DIR)}/tokens.{css,js}`);
